{"intent": "refund_return", "model_score": 0.9, "alt": []}
Message: 'I was charged twice for my subscription this month'
{"intent": "refund_return", "model_score": 0.9, "alt": []}
Message: "I cannot own any Alexa device because it won't link to my account"
{"intent": "device_app_account", "model_score": 0.9, "alt": []}
